/* Internal, unregistered transport API. No NAS traffic is generated by arm,
 * ready or poll. Upper-layer reads require an admitted explicit write. */
#include <sys/hk_abp_nas_worker.h>
#include <sys/hk_qrtr_wire.h>
#ifdef KERNEL
#include <sys/errno.h>
#else
#include <errno.h>
#endif

#define RX_CLOSED (1u << 31)
#define RX_COUNT (RX_CLOSED - 1)

static int
configure(struct hk_abp_nas_worker *w, struct hk_qrtr_mhi *mhi,
    const struct hk_abp_nas_worker_ops *ops, void *context, bool restart)
{
    if (!w || !mhi || !ops || !ops->lock || !ops->unlock || !ops->is_owner)
        return EINVAL;
    if (mhi->up)
        return EBUSY;
    unsigned phase = hk_qo_phase(&w->gate);
    if (restart) {
        if (phase != HK_QO_DRAINED || __atomic_load_n(&w->admission,__ATOMIC_ACQUIRE) != RX_CLOSED)
            return EBUSY;
    } else if (phase != HK_QO_OFF) {
        return EBUSY;
    }
    uint64_t generation = __atomic_load_n(&w->generation,__ATOMIC_RELAXED);
    if (generation == UINT64_MAX)
        return EOVERFLOW;

    /* Exclusive board setup. Attached producer and consumer sources from the
     * previous generation must already have been disconnected and joined.
     * Preserve backend.serial: a retired lease will never name a new open. */
    w->mhi = mhi;
    w->ops = ops;
    w->context = context;
    w->discarded = 0;
    __builtin_memset(&w->inbox,0,sizeof(w->inbox));
    __atomic_store_n(&w->generation,generation+1,__ATOMIC_RELEASE);
    __atomic_store_n(&w->admission,0,__ATOMIC_RELEASE);
    if (!hk_qo_move(&w->gate,phase,HK_QO_ARMED))
        return EBUSY;
    return 0;
}

int
hk_abp_worker_arm(struct hk_abp_nas_worker *w, struct hk_qrtr_mhi *mhi,
    const struct hk_abp_nas_worker_ops *ops, void *context)
{
    return configure(w,mhi,ops,context,false);
}

int
hk_abp_worker_rearm_after_disconnect(struct hk_abp_nas_worker *w, struct hk_qrtr_mhi *mhi,
    const struct hk_abp_nas_worker_ops *ops, void *context)
{
    return configure(w,mhi,ops,context,true);
}

uint64_t
hk_abp_worker_generation(const struct hk_abp_nas_worker *w)
{
    return w ? __atomic_load_n(&w->generation,__ATOMIC_ACQUIRE) : 0;
}

int
hk_abp_worker_ready(struct hk_abp_nas_worker *w)
{
    if (!w || !hk_qo_ready(&w->gate))
        return EINVAL;
    return 0;
}

static bool
producer_enter(struct hk_abp_nas_worker *w)
{
    unsigned current = __atomic_load_n(&w->admission,__ATOMIC_ACQUIRE);
    do {
        if ((current & RX_CLOSED) || current == RX_COUNT)
            return false;
    } while (!__atomic_compare_exchange_n(&w->admission,&current,current+1,
        false,__ATOMIC_ACQ_REL,__ATOMIC_ACQUIRE));
    return true;
}

int
hk_abp_worker_rx(struct hk_abp_nas_worker *w, uint64_t generation, const void *p, size_t n)
{
    if (!w || !generation || hk_qo_phase(&w->gate)==HK_QO_OFF)
        return ENXIO;
    if (!producer_enter(w))
        return ECANCELED;

    int result = 0;
    if (generation != hk_abp_worker_generation(w)) {
        result = ESTALE;
    } else {
        w->ops->lock(w->context);
        if (hk_qo_phase(&w->gate)>=HK_QO_STOP)
            hk_qi_close(&w->inbox);
        if (!hk_qi_push(&w->inbox,p,n)) {
            if (w->inbox.closed)
                result = ECANCELED;
            else if (!p || !n || n>HK_QI_MAX)
                result = EMSGSIZE;
            else
                result = ENOBUFS;
        }
        w->ops->unlock(w->context);
    }
    /* No access to the inbox or transport after dropping this reference. */
    __atomic_sub_fetch(&w->admission,1,__ATOMIC_RELEASE);
    return result;
}

void
hk_abp_worker_stop(struct hk_abp_nas_worker *w)
{
    if (!w)
        return;
    __atomic_fetch_or(&w->admission,RX_CLOSED,__ATOMIC_ACQ_REL);
    hk_qo_stop(&w->gate);
}

static int
enter_owner(struct hk_abp_nas_worker *w)
{
    if (!w || hk_qo_phase(&w->gate)==HK_QO_OFF)
        return ENXIO;
    if (!w->ops->is_owner(w->context))
        return EPERM;
    if (w->busy)
        return EBUSY;
    unsigned phase = hk_qo_phase(&w->gate);
    if (phase == HK_QO_ARMED)
        return EAGAIN;
    if (phase != HK_QO_READY)
        return ECANCELED;
    w->ops->lock(w->context);
    bool loss = w->inbox.overflow || w->inbox.rejected;
    w->ops->unlock(w->context);
    if (loss) {
        hk_abp_worker_stop(w);
        return ENOBUFS;
    }
    w->busy = true;
    return 0;
}

int
hk_abp_worker_poll_observed(struct hk_abp_nas_worker *w,
    void (*control)(const struct hk_qrtr_wire_datagram *))
{
    int err = enter_owner(w);
    if (err)
        return err;
    if (!w->attached) {
        hk_qrtr_mhi_set_up(w->mhi,true);
        w->online = true;
        err = hk_abp_nas_attach(&w->backend,w->mhi);
        if (err) {
            hk_abp_worker_stop(w);
            w->busy = false;
            return err;
        }
        w->attached = true;
    }

    for (unsigned i=0; i<HK_QI_SLOTS && hk_qo_phase(&w->gate)==HK_QO_READY; ++i) {
        w->ops->lock(w->context);
        bool loss = w->inbox.overflow || w->inbox.rejected;
        size_t n = 0;
        if (!loss)
            n = hk_qi_pop(&w->inbox,w->packet);
        w->ops->unlock(w->context);
        if (loss) {
            hk_abp_worker_stop(w);
            err = ENOBUFS;
            break;
        }
        if (!n)
            break;
        /* This NAS worker terminates local service ports only. SDX55's QRTR
         * router forwards DATA for other nodes; such a packet does not
         * belong to a same-numbered port here. Leave control-port aliases
         * and discovery on the transport's usual path. The MHI adapter
         * still owns malformed-frame accounting. */
        struct hk_qrtr_wire_datagram d;
        bool decoded = hk_qrtr_wire_decode(w->packet,n,HK_QRTR_CORE_MAX_PAYLOAD,&d) == 0;
        if (decoded &&
            d.type == HK_QRTR_WIRE_DATA && d.to_port != HK_QRTR_WIRE_PORT_CONTROL &&
            d.to_node != w->mhi->core.local_node)
            continue;
        /* No queue lock is held across dispatch or an emit callback. */
        int rc = hk_qrtr_mhi_input(w->mhi,w->packet,n);
        if (control && !rc && decoded && d.to_port == HK_QRTR_WIRE_PORT_CONTROL)
            control(&d);
    }
    if (hk_qo_phase(&w->gate)==HK_QO_READY)
        hk_qrtr_mhi_fresh(w->mhi);
    else if (!err)
        err = ECANCELED;
    w->busy = false;
    return err;
}

int
hk_abp_worker_poll(struct hk_abp_nas_worker *w)
{
    return hk_abp_worker_poll_observed(w, NULL);
}

int
hk_abp_worker_open(struct hk_abp_nas_worker *w, const char *name, size_t len,
    hk_qmux_emit_t emit, void *context, uint64_t *lease)
{
    if (lease)
        *lease = 0;
    int err = enter_owner(w);
    if (err)
        return err;
    err = EAGAIN;
    if (w->attached)
        err = hk_abp_nas_open(&w->backend,name,len,emit,context,lease);
    w->busy = false;
    return err;
}

int
hk_abp_worker_write(struct hk_abp_nas_worker *w, uint64_t lease,
    const uint8_t *frame, size_t n)
{
    int err = enter_owner(w);
    if (err)
        return err;
    err = ENOTCONN;
    if (w->attached)
        err = hk_abp_nas_write(&w->backend,lease,frame,n);
    w->busy = false;
    return err;
}

int
hk_abp_worker_close(struct hk_abp_nas_worker *w, uint64_t lease)
{
    int err = enter_owner(w);
    if (err)
        return err;
    err = ENOTCONN;
    if (w->attached)
        err = hk_abp_nas_close(&w->backend,lease);
    w->busy = false;
    return err;
}

bool
hk_abp_worker_drained(const struct hk_abp_nas_worker *w)
{
    return w && hk_qo_phase(&w->gate)==HK_QO_DRAINED;
}

bool
hk_abp_worker_timeout(struct hk_abp_nas_worker *w)
{
    if (!w)
        return false;
    hk_abp_worker_stop(w);
    return hk_qo_timeout(&w->gate)==HK_QO_DRAINED;
}

static void
retire_queue(struct hk_abp_nas_worker *w)
{
    w->ops->lock(w->context);
    hk_qi_close(&w->inbox);
    unsigned remaining = w->inbox.head - w->inbox.tail;
    w->discarded += remaining;
    w->inbox.retired += remaining;
    w->inbox.tail = w->inbox.head;
    w->ops->unlock(w->context);
}

int
hk_abp_worker_finish(struct hk_abp_nas_worker *w)
{
    if (!w || !w->ops || !w->ops->is_owner(w->context))
        return EPERM;
    if (w->busy)
        return EBUSY;
    unsigned phase = hk_qo_phase(&w->gate);
    if (phase != HK_QO_STOP && phase != HK_QO_HELD)
        return EINVAL;
    if (__atomic_load_n(&w->admission,__ATOMIC_ACQUIRE)!=RX_CLOSED)
        return EAGAIN;

    w->busy = true;
    retire_queue(w);
    if (w->attached) {
        hk_abp_nas_detach(&w->backend);
        w->attached = false;
    }
    if (w->online) {
        hk_qrtr_mhi_set_up(w->mhi,false);
        w->online = false;
    }
    w->busy = false;
    /* No transport access after ACK. A late ACK cannot undo quarantine. */
    return hk_qo_ack(&w->gate) ? 0 : ETIMEDOUT;
}

bool
hk_abp_worker_never_started(struct hk_abp_nas_worker *w)
{
    if (!w || !w->ops)
        return false;
    unsigned phase = hk_qo_phase(&w->gate);
    if (phase!=HK_QO_ARMED && phase!=HK_QO_STOP)
        return false;
    hk_abp_worker_stop(w);
    if (__atomic_load_n(&w->admission,__ATOMIC_ACQUIRE)!=RX_CLOSED)
        return false;
    retire_queue(w);
    return hk_qo_no_worker(&w->gate);
}
